package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import java.time.*;
import java.util.*;
import javax.sql.DataSource;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.PlatformTransactionManager;

/** Actual native generic INPUT and immutable initial request; no entity-analysis consumer or paid call is claimed. */
class CatalogAnalysisPreparedInputTest {
    boolean mysql(){return false;}
    CatalogAnalysisInputProfileTest helper(){return new CatalogAnalysisInputProfileTest(){@Override boolean mysql(){return CatalogAnalysisPreparedInputTest.this.mysql();}};}
    record Stored(CatalogAnalysisInputProfileTest.Built original,GenerationFlowService.Frozen input){ }
    Stored stored(String category,boolean alias){var helper=helper();var built=helper.fixture(category,alias);var base=CatalogAnalysisInputProfile.create(built.captured(),helper.settings);var full=helper.enrich(built,base);var complete=CatalogAnalysisInputProfile.complete(full);var reservation=built.data().receipt();String root=JdbcCatalogAnalysisPreparedInputs.root(reservation.intentId()),action=JdbcCatalogAnalysisPreparedInputs.action(root);Instant now=built.data().outer().completed.plusSeconds(120);var command=complete.command();String hash=CanonicalJson.hash(CanonicalJson.Domain.INPUT,full),request=new GenerationRequestBuilder().build(command.stage(),complete.snapshotJson(),hash);var snapshot=CanonicalJson.parse(complete.snapshotJson());var missing=snapshot.get("missing").valueStream().map(tools.jackson.databind.JsonNode::asText).toList();var frozen=new GenerationFlowService.Frozen(root,command.logicalKey(),command.generation(),command.stage(),built.captured().dayEvidence().original().cutoff(),snapshot.get("coverage_state").asText(),missing,complete.snapshotJson(),hash,request,command.stage().priority(),now,"queued");var f=built.data().f();f.write(()->{built.provider().verify(built.captured());new GenerationJdbcStore(f.f.source,Clock.fixed(now,ZoneOffset.UTC),JdbcCatalogAnalysisPreparedInputs.ACTOR,root,command).save(frozen,action);return true;});return new Stored(built,frozen);}
    CatalogAnalysisPreparedInputService reader(Stored built,Clock clock){var f=built.original().data().f();return new CatalogAnalysisPreparedInputService(f.f.source,f.f.tx,clock,f.f.category);}
    @Test void FourCategoriesReadTheSameCompleteNativeInputInitialRequestAndTypedLineage(){for(String category:List.of("agent","skill","workflow","model")){var built=stored(category,false);var service=reader(built,mock(Clock.class));var data=built.original().data();var read=service.find(data.outer().day,data.receipt().entityId());assertEquals(built.input(),read.input());assertEquals(data.receipt().json(),read.reservation().json());assertEquals(built.input(),data.f().write(()->service.lockInWriter(data.outer().day,data.receipt().entityId())).input());assertEquals(0,data.f().f.jdbc.queryForObject("SELECT call_count FROM jobs WHERE id=?",Integer.class,built.input().ownerId()));assertEquals(2,data.f().f.sends);assertFalse(read.toString().contains("fictional"));}}
    @Test void VersionGenerationTwoUsesRealOriginalLineageAndBothAliasBodies(){var built=stored("agent",true);var data=built.original().data();var read=reader(built,mock(Clock.class)).find(data.outer().day,data.receipt().entityId());assertEquals(2,read.input().generation());assertEquals(2,CanonicalJson.parse(read.input().snapshotJson()).get("members").size());assertEquals(CatalogPreviousAnalysisTest.Fixture.ROOT,data.f().f.jdbc.queryForObject("SELECT supersedes_job_id FROM jobs WHERE id=?",String.class,read.input().ownerId()));assertEquals(2,data.f().f.sends);}
    @Test void RestartOriginalReadNeedsNoCurrentTablesOrClock(){var built=stored("model",false);var data=built.original().data();for(String table:List.of("sources","source_run_items","analyzed_entities","contents"))data.f().f.jdbc.execute("DROP TABLE "+table);Clock clock=mock(Clock.class);assertEquals(built.input(),reader(built,clock).find(data.outer().day,data.receipt().entityId()).input());verifyNoInteractions(clock);assertEquals(2,data.f().f.sends);}
    @Test void UnpreparedOrAbsentReservationDoesNotInventInput(){var helper=helper();var built=helper.fixture("skill",false);var f=built.data().f();var service=new CatalogAnalysisPreparedInputService(f.f.source,f.f.tx,mock(Clock.class),"skill");assertNull(service.find(built.data().outer().day,built.data().receipt().entityId()));assertNull(service.find(built.data().outer().day,"fictional-absent-entity"));assertEquals(0,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE intent_id=?",Integer.class,built.data().receipt().intentId()));assertEquals(2,f.f.sends);}
    @Test void DamagedNativePreparationInputInitialRequestOrLineageCannotBeReplayed(){var built=stored("workflow",false);var data=built.original().data();var f=data.f();var service=reader(built,mock(Clock.class));String action=JdbcCatalogAnalysisPreparedInputs.action(built.input().ownerId()),receipt=JdbcFrozenInputs.stableId("prepare-action",action);assertThrows(RuntimeException.class,()->f.write(()->{f.f.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE id=?",new byte[32],receipt);return service.lockInWriter(data.outer().day,data.receipt().entityId());}));assertThrows(RuntimeException.class,()->f.write(()->{f.f.jdbc.update("UPDATE jobs SET payload_hash=? WHERE record_kind='snapshot_part' AND owner_job_id=? AND purpose='input'",new byte[32],built.input().ownerId());return service.lockInWriter(data.outer().day,data.receipt().entityId());}));assertThrows(RuntimeException.class,()->f.write(()->{f.f.jdbc.update("UPDATE jobs SET request_json='{}' WHERE id=?",JdbcFrozenInputs.stableId("attempt",built.input().ownerId()+":1"));return service.lockInWriter(data.outer().day,data.receipt().entityId());}));assertThrows(RuntimeException.class,()->f.write(()->{f.f.jdbc.update("UPDATE jobs SET supersedes_job_id='fictional-wrong-parent' WHERE id=?",built.input().ownerId());return service.lockInWriter(data.outer().day,data.receipt().entityId());}));assertEquals(built.input(),service.find(data.outer().day,data.receipt().entityId()).input());assertEquals(2,f.f.sends);}
    @Test void OversizedOriginalRequestIsRejectedBeforeGenericRequestLoading(){var built=stored("agent",false);var data=built.original().data();var request=tools.jackson.databind.json.JsonMapper.shared().createObjectNode().put("fictional","x".repeat(1048576));data.f().f.jdbc.update("UPDATE jobs SET request_json=? WHERE id=?",JdbcFrozenInputs.canonical(request),JdbcFrozenInputs.stableId("attempt",built.input().ownerId()+":1"));assertThrows(RuntimeException.class,()->reader(built,mock(Clock.class)).find(data.outer().day,data.receipt().entityId()));assertEquals(2,data.f().f.sends);}
    @Test void ExactLookupRolesAndMandatoryClosedConstructionDoNoIo(){var built=stored("skill",false);var data=built.original().data();var reader=reader(built,mock(Clock.class));assertThrows(RuntimeException.class,()->reader.read(data.outer().day,data.receipt().entityId()));assertThrows(RuntimeException.class,()->reader.lockInWriter(data.outer().day,data.receipt().entityId()));assertThrows(RuntimeException.class,()->data.f().write(()->reader.find(data.outer().day,data.receipt().entityId())));assertThrows(RuntimeException.class,()->data.outer().snapshot(data.f(),()->reader.lockInWriter(data.outer().day,data.receipt().entityId())));var source=mock(DataSource.class);var tx=mock(PlatformTransactionManager.class);var clock=mock(Clock.class);for(String category:List.of("agent","skill","workflow","model"))assertNotNull(new CatalogAnalysisPreparedInputService(source,tx,clock,category));verifyNoInteractions(source,tx,clock);assertThrows(RuntimeException.class,()->new CatalogAnalysisPreparedInputService(source,tx,clock,"news_tech"));}
}
